body:
I have already done that @vvo. For example at category page (/women-clothes) if I click on a sub category (dresses) in hierarchicalMenu widget I want pathname to be /dresses.

My current configuration:

```javascript
var locationPath = window.location.pathname;
var searchParameters = {
    hierarchicalFacetsRefinements : {category: ['Women > Clothes']}
}
var defaultParams = {
    appId: 'XXXXXX',
    apiKey: 'XXXXXX',
    indexName: 'XXXXXX',
    searchParameters: searchParameters,
    urlSync:{
        useHash: false,
        trackedParameters:['query','page','facetsRefinements','disjunctiveFacetsRefinements','numericRefinements']
    }
}
var search = instantsearch(defaultParams);
var firstTime = true;
search.on('render', function() {
    $('#categories a').click(function(){
        locationPath =  '/'+$(this).data('slug');
    });
    if(!firstTime){
        ga('set', 'page', locationPath);
        ga('send', 'pageview');
    }
    firstTime = false;
});
```

Then I downloaded instantsearch.js and edited that line;

```javascript
function getFullURL(relative) {
    //return getLocationOrigin() + window.location.pathname + relative;
    return getLocationOrigin() + locationPath + relative;
}
```

So I will need to check new versions of instantsearch.js, download again and update 😖

But such a solution would be great:

```javascript
var defaultParams = {
    appId: 'XXXXXX',
    apiKey: 'XXXXXX',
    indexName: 'XXXXXX',
    locationPath: window.location.pathname,
    searchParameters: searchParameters,
    urlSync:{
        useHash: false,
        trackedParameters:['query','page','facetsRefinements','disjunctiveFacetsRefinements','numericRefinements']
    }
}
var search = instantsearch(defaultParams);
search.on('render', function() {
    $('#categories a').click(function(){
        search.helper.setLocationPath('/'+$(this).data('slug'));
    });
}
```
